-- ---- mesa-save-queen/sql/030-enable-save-queen.sql ----
DELIMITER //
BEGIN NOT ATOMIC
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;RESIGNAL;END;
START TRANSACTION;

IF(SELECT COUNT(*)FROM tasks WHERE id BETWEEN 3040469 AND 3040473 AND enabled IN(0,1))<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Save the Queen enable state differs';END IF;
UPDATE tasks SET enabled=1 WHERE id BETWEEN 3040469 AND 3040473 AND enabled=0;
IF(SELECT COUNT(*)FROM achievement_criteria WHERE achievement_id=500040900 AND component_type=1 AND component_id BETWEEN 50166 AND 50170 AND enabled IN(0,1))<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Save the Queen enable state differs';END IF;
UPDATE achievement_criteria SET enabled=1 WHERE achievement_id=500040900 AND component_type=1 AND component_id BETWEEN 50166 AND 50170 AND enabled=0;

COMMIT;
END//
DELIMITER ;
